  if (arr[mid] == arr[mid - 1]) {
    left = arr.slice(0, mid - 1);
    right = arr.slice(mid + 1);
  } else if (arr[mid] == arr[mid + 1]) {
    left = arr.slice(0, mid);
    right = arr.slice(mid + 2);
