var singleNonDuplicate1 = function (arr) {
  if (!arr.length) return null;
  if (arr.length === 1) return arr[0];
  let l = 0,
    h = arr.length - 1,
    t = -1;
  //二分法版本
  while (l <= h) {
    let m = Math.floor(l + (h - l) / 2);
    if (arr[m] === arr[m - 1]) {
      //左边偶
      (m - 2) % 2 === 0 ? (h = m - 2) : (l = m + 1);
