var searchRange = function (nums, target) {
  let res = [-1, -1];
  let leftIdx = searchHelp(nums, target, true);

  if (leftIdx == nums.length || nums[leftIdx] != target) {
    return res;
  }

  res[0] = leftIdx;
  res[1] = searchHelp(nums, target, false) - 1;
  return res;
};

function searchHelp(nums, target, isLeft) {
  let lo = 0;
  let hi = nums.length;

  while (lo < hi) {
    let mid = Math.floor((lo + hi) / 2);
    if (nums[mid] > target || (isLeft && target == nums[mid])) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return lo;
}

