function qSort(nums) {
  if (nums.length <= 1) {
    return nums;
  }
  let mid = Math.floor(nums.length / 2);
  let left = [];
  let right = [];
  let pivot = nums.splice(mid, 1)[0];
  for (let i = 0; i < nums.length; i++) {
    let item = nums[i];
    if (item > pivot) {
      right.push(item);
    } else {
      left.push(item);
    }
  }
  console.log(pivot, left, right);
  return qSort(left).concat([pivot], qSort(right));
}

